def lru_cache(operations, capacity):
    from collections import OrderedDict

    cache = OrderedDict()
    results = []

    for op in operations:
        if op[0] == "get":
            key = op[1]
            if key in cache:
                value = cache.pop(key)
                cache[key] = value
                results.append(value)
            else:
                results.append(None)
        elif op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache.pop(key)
            cache[key] = value
            if capacity == 0:
                cache.clear()
            elif len(cache) > capacity:
                cache.popitem(last=False)

    return results
